'use strict';
const $ = (s) => document.querySelector(s);
const icons = {
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5"/>',
 memories:'<rect x="4" y="5" width="16" height="15" rx="3"/><path d="M8 3v4m8-4v4M4 10h16m-12 4h2m4 0h2m-8 3h2"/>',
 us:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',chevron:'<path d="m9 6 6 6-6 6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 spark:'<path d="m12 2 2.7 7.3L22 12l-7.3 2.7L12 22l-2.7-7.3L2 12l7.3-2.7L12 2Z"/>',
 check:'<path d="m5 12 4 4L19 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',
 heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
 leaf:'<path d="M20 3C9 2 3 6 5 14s15 8 15-11Z M4 21l12-13"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 question:'<circle cx="12" cy="12" r="9"/><path d="M9.5 8a2.5 2.5 0 0 1 5 .7c0 2-2.5 2-2.5 4m0 3v.1"/>',
 choice:'<path d="M5 4h4v4H5zm10 12h4v4h-4zM7 8v7a3 3 0 0 0 3 3h5m-8-6h7a3 3 0 0 0 3-3V4m-3 3 3-3 3 3"/>',
 action:'<path d="m8 12 3 3 5-6"/><circle cx="12" cy="12" r="9"/>',
 book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v15"/>'
};
const icon = (name) => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.spark}</svg>`;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catalog = [
 {type:'Appreciation',icon:'spark',title:'The little things',prompt:'What’s one little thing they do that means more than they know?',note:'The everyday things are often the things that matter most.',hint:'Something only you would notice…',partner:'The way you always ask how my day really went. Even on the busy days, you make me feel like I matter.',sample:'You remember the little things I mention, even when I’ve forgotten them myself.'},
 {type:'Question',icon:'question',title:'Our kind of happy',prompt:'If we could press pause on everything for an afternoon, what would we do?',note:'No schedules. No to-do lists. Just a little time for the two of you.',hint:'My perfect afternoon with you would be…',partner:'A long walk somewhere quiet, picking up our favorite snacks, and coming home with absolutely no plans.',sample:'A slow afternoon by the water, a coffee, and nowhere we need to be.'},
 {type:'Choice',icon:'choice',title:'Same page, different plans',prompt:'We have a free evening. What sounds most like us?',note:'Pick your favorite. You’ll find out whether you’re dreaming of the same thing.',options:['A cozy night in','A spontaneous little adventure','Dinner somewhere new','A sunset walk'],partner:'A cozy night in',sample:'A sunset walk'},
 {type:'Action',icon:'action',title:'A little extra love',prompt:'Leave your partner a little note somewhere they’ll find it.',note:'One sentence is enough. Tell them something you’re glad you get to share with them.',partner:'Done — a little note, just for you.',sample:'Done — a little note, just for you.'},
 {type:'Check-in',icon:'sun',title:'A little closer',prompt:'How connected are you feeling today?',note:'There’s no right answer. This is a small chance to understand each other.',partner:'4 out of 5',sample:'4 out of 5'}
];
catalog.push(
 {type:'Question',icon:'leaf',title:'A fresh start',prompt:'What’s one small thing that would help us feel like a team again?',note:'Start with something kind, specific, and possible. You don’t have to solve everything today.',hint:'One small step that would help me is…',partner:'A little time to listen to each other without trying to solve everything at once.',sample:'A calm check-in where we both get a chance to finish our thoughts.'},
 {type:'Question',icon:'question',title:'Feeling understood',prompt:'When words are hard, what helps you feel heard?',note:'You can need time, reassurance, or a quieter way to say it. Let each other know.',hint:'It helps me when…',partner:'A little patience, a softer tone, and knowing we can take a break and come back.',sample:'Knowing I can pause to find my words without feeling rushed.'},
 {type:'Choice',icon:'choice',title:'Close from a distance',prompt:'What little long-distance ritual would you love this week?',note:'Choose a small way to feel included in each other’s ordinary days.',options:['A good-morning voice note','A phone-free video dinner','A walk while we call','A shared movie night'],partner:'A walk while we call',sample:'A good-morning voice note'},
 {type:'Appreciation',icon:'spark',title:'Our everyday us',prompt:'What’s an ordinary moment with us you’d like more of?',note:'It doesn’t have to be a big date. Sometimes the smallest moments feel like home.',hint:'I’d love more of…',partner:'Making something simple for dinner together and catching up without our phones.',sample:'A slow morning with coffee and no rush.'}
);

const KEY='moment_demo_v1';
let storageAvailable=true;
function dateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function shiftDay(key,n){const d=new Date(key+'T12:00:00');d.setDate(d.getDate()+n);return dateKey(d);}
function prettyDate(key,options){return new Date(key+'T12:00:00').toLocaleDateString('en-US',options);}
function initialState(){
 const day=dateKey(new Date());
 return {version:1,me:'Alexa',partner:'Jamie',tab:'today',date:day,index:0,answer:'',draft:'',partnerDone:false,revealed:false,reminders:false,evening:false,wellbeingByDay:{},debriefs:[],focus:[],focusSetupSeen:false,todos:[],
 history:Array.from({length:6},(_,i)=>{const c=catalog[(i+1)%catalog.length];return {date:shiftDay(day,-i-1),index:(i+1)%catalog.length,me:c.sample,partner:c.partner};})};
}
function validState(s){return s&&s.version===1&&['today','todo','features','memories','us'].includes(s.tab)&&typeof s.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s.date)&&Number.isInteger(s.index)&&s.index>=0&&s.index<catalog.length&&typeof s.me==='string'&&typeof s.partner==='string'&&typeof s.answer==='string'&&typeof s.draft==='string'&&Array.isArray(s.history)&&s.history.every(r=>typeof r.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(r.date)&&Number.isInteger(r.index)&&r.index>=0&&r.index<catalog.length&&typeof r.me==='string'&&typeof r.partner==='string');}
function load(){try{const s=JSON.parse(localStorage.getItem(KEY));if(validState(s))return s;}catch(e){storageAvailable=false;}return initialState();}
let state=load();let modalName=null;let returnFocus=null;let toastTimer;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageAvailable=false;}}
function streak(){const set=new Set(state.history.map(h=>h.date));let d=set.has(state.date)?state.date:shiftDay(state.date,-1),n=0;while(set.has(d)&&n<10000){n++;d=shiftDay(d,-1);}return n;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function navigate(tab){state.tab=tab;persist();render();window.scrollTo({top:0,behavior:'instant'});}
function nav(){return [['today','sun','Today'],['todo','action','To Do'],['features','spark','Features'],['memories','memories','Memories'],['us','us','Us']].map(([key,i,label])=>`<button class="nav-item ${state.tab===key?'active':''}" data-action="tab" data-tab="${key}" ${state.tab===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('');}
function render(){
 $('#desktop-nav').innerHTML=nav();$('#mobile-nav').innerHTML=nav();
 $('#profile-button').innerHTML=esc(state.me.charAt(0).toUpperCase())+`<span class="avatar-overlap">${esc(state.partner.charAt(0).toUpperCase())}</span>`;
 $('#main').innerHTML=`<div class="fade-in">${!storageAvailable?'<p class="storage-notice">Browser storage is unavailable. This demo works, but changes won’t survive a refresh.</p>':''}${state.tab==='today'?today():state.tab==='todo'?todoPage():state.tab==='features'?featuresPage():state.tab==='memories'?memories():us()}</div>`;
 document.title=`${state.tab.charAt(0).toUpperCase()+state.tab.slice(1)} · Moment Demo`;
}
function pageHeading(kicker,title,subtitle){return `<div class="topline"><span class="date">${kicker}</span><span class="subtle-badge">Your shared space</span></div><h1>${title}</h1><p class="intro">${subtitle}</p>`;}
function partnerStrip(){return `<div class="partner-strip"><div class="partner-status"><span class="mini-avatar">${esc(state.me.charAt(0))}</span><span>${esc(state.me)}</span><span class="status-dot ${state.answer?'done':''}"></span><span class="${state.answer?'status-text':''}">${state.answer?'Done':'Your turn'}</span></div><div class="partner-status"><span class="mini-avatar lilac">${esc(state.partner.charAt(0))}</span><span>${esc(state.partner)}</span><span class="status-dot ${state.partnerDone?'done':''}"></span><span class="${state.partnerDone?'status-text':''}">${state.partnerDone?'Done':'Not yet'}</span></div></div>`;}
function streakCard(){return `<section class="streak-card" aria-label="Shared streak"><div class="streak-head"><span class="eyebrow">OUR LITTLE HABIT</span>${icon('leaf')}</div><div class="streak-value"><strong>${streak()}</strong><span>days together</span></div><p>A little time for each other.<br>One day at a time.</p><div class="week">${Array.from({length:7},(_,i)=>{const d=shiftDay(state.date,i-6),done=state.history.some(h=>h.date===d);return `<div class="day">${prettyDate(d,{weekday:'narrow'})}<span class="${done?(i===6?'today-done':'filled'):(i===6?'current':'')}">${done?icon('check'):'·'}</span></div>`;}).join('')}</div></section>`;}
function today(){return simpleToday();}

function entry(c){let form='';if(c.type==='Choice'){form=`<div class="options" role="group" aria-label="Choose your answer">${c.options.map(o=>`<button class="option ${state.draft===o?'selected':''}" aria-pressed="${state.draft===o}" data-action="choose" data-value="${esc(o)}"><span class="radio"></span>${esc(o)}</button>`).join('')}</div>`;}else if(c.type==='Check-in'){form=`<div class="rating" role="group" aria-label="Connection rating">${[1,2,3,4,5].map(n=>`<button aria-label="${n} out of 5" aria-pressed="${state.draft===n+' out of 5'}" class="${state.draft===n+' out of 5'?'selected':''}" data-action="choose" data-value="${n} out of 5">${n}</button>`).join('')}</div><div class="rating-ends"><span>A little distant</span><span>Really connected</span></div>`;}else if(c.type==='Action'){form=`<div class="action-art">${icon('heart')}</div><p class="prompt-note" style="margin-bottom:22px">Take a minute to do it, then mark your part complete.</p>`;}else{form=`<div class="answer-wrap"><label class="field-label" for="answer">YOUR LITTLE MOMENT</label><textarea id="answer" maxlength="1200" placeholder="${esc(c.hint)}">${esc(state.draft)}</textarea><div class="field-hint"><span>Just a sentence or two is lovely.</span><span id="count">${state.draft.length}/1200</span></div></div>`;}return `<div class="moment-type">${icon(c.icon)} ${c.type}</div><h2 class="moment-question">${esc(c.prompt)}</h2><p class="prompt-note">${esc(c.note)}</p>${form}<button id="submit-answer" class="primary" data-action="submit" ${c.type!=='Action'&&!state.draft.trim()?'disabled':''}>${c.type==='Action'?'I did my part':'Save my Moment'} ${icon('arrow')}</button>`;}
function waiting(c){return `<div class="waiting-art">${icon('lock')}</div><h2 class="waiting-title">A little anticipation.</h2><p class="waiting-copy">Your part is done. Once ${esc(state.partner)} finishes, your Moment will be ready to open together.</p><div class="saved-answer"><span>YOUR ${c.type==='Action'?'MOMENT':'ANSWER'} · SAVED</span><p>${esc(state.answer)}</p></div><div class="demo-action"><p>Try the other half of the experience.</p><button data-action="partner">Simulate ${esc(state.partner)} finishing ${icon('arrow')}</button></div>`;}
function ready(){return `<div class="waiting-art">${icon('spark')}</div><h2 class="waiting-title">Your Moment is ready.</h2><p class="waiting-copy">You both showed up. Now take a little look at what you shared.</p><button class="primary" data-action="reveal">Reveal our Moment ${icon('arrow')}</button><p class="reveal-footer">${icon('check')} One more day of choosing each other.</p>`;}
function reveal(c,record){const me=record?record.me:state.answer,partner=record?record.partner:c.partner;return `<div style="margin-top:24px"><span class="success-pill">${icon('check')} YOUR MOMENT, COMPLETE</span></div><h2 class="reveal-heading">You made time for<br>each other today.</h2><p class="prompt-note">${esc(c.prompt)}</p><div class="response"><span class="response-label">${icon('spark')} ${esc(state.me)}</span><p>${esc(me)}</p></div><div class="response partner"><span class="response-label">${icon('spark')} ${esc(state.partner)}</span><p>${esc(partner)}</p></div>${c.type==='Choice'?`<div class="selection-match">${me===partner?'A little match. You’re on the same page.':'Different picks. A lovely place to start a conversation.'}</div>`:''}${record?'':`<div class="reveal-footer">${streak()} days of little moments. Here’s to more.</div><button class="secondary completed-cta" data-action="tab" data-tab="memories">Visit our Memories ${icon('arrow')}</button><div class="demo-action"><p>Want to explore another kind of Moment?</p><button data-action="next">Try the next demo day ${icon('arrow')}</button></div>`}`;}
function memories(){const list=[...state.history].sort((a,b)=>b.date.localeCompare(a.date));return `${pageHeading('OUR MEMORIES','Little moments.<br><em>A story of us.</em>','The things you shared. The time you made. Yours to return to.')}<div class="memories-intro">${icon('book')}<div><p>${list.length} little reasons to feel closer.</p><span>Sample memories + the Moments you complete in this demo.</span></div></div><div class="history-head"><h2>Your shared story</h2><span>${list.length} Moments</span></div><div class="history-list">${list.map(r=>{const c=catalog[r.index];return `<button class="memory-row" data-action="memory" data-date="${r.date}" aria-label="Open ${esc(c.title)} from ${prettyDate(r.date,{month:'long',day:'numeric'})}"><div class="date-tile"><span>${prettyDate(r.date,{month:'short'})}</span><strong>${prettyDate(r.date,{day:'numeric'})}</strong></div><div class="memory-text"><span>${c.type} · Both completed</span><h3>${esc(c.prompt)}</h3></div>${icon('chevron')}</button>`;}).join('')}</div>${reflectionMemories()}${debriefMemories()}<p class="gentle-note">Your little archive of showing up for each other.</p>`;}
function us(){return `${pageHeading('THE TWO OF YOU','Our own<br><em>little corner.</em>','A shared habit. A little intention. A whole lot of us.')}<section class="us-card"><div class="couple-avatars"><span>${esc(state.me.charAt(0))}</span><span>${esc(state.partner.charAt(0))}</span></div><h2>${esc(state.me)} & ${esc(state.partner)}</h2><div class="connection-label"><i></i> Connected sample couple</div><div class="us-stats"><div class="stat"><strong>${streak()}</strong><span>day shared streak</span></div><div class="stat"><strong>${state.history.length}</strong><span>Moments together</span></div></div><button class="edit-link" data-action="edit">Make the demo yours</button></section>${focusCard()}${foundationsCard()}<div class="settings-section"><p class="eyebrow">A LITTLE ROUTINE</p><div class="settings-group"><button class="setting-row" role="switch" aria-checked="${state.reminders}" data-action="toggle" data-field="reminders"><div><span>Your daily Moment</span><p>Reminder preview · no notification is sent</p></div><span class="toggle ${state.reminders?'on':''}"><i></i></span></button><button class="setting-row" role="switch" aria-checked="${state.evening}" data-action="toggle" data-field="evening"><div><span>A gentle evening nudge</span><p>Reminder preview · no notification is sent</p></div><span class="toggle ${state.evening?'on':''}"><i></i></span></button></div></div><div class="settings-section"><p class="eyebrow">YOUR SHARED SPACE</p><div class="settings-group"><button class="setting-row" data-action="pair"><div><span>Partner pairing preview</span><p>Try the sample partner code</p></div>${icon('chevron')}</button><button class="setting-row" data-action="privacy"><div><span>Privacy & this demo</span><p>What’s real, and what’s a preview</p></div>${icon('chevron')}</button><button class="setting-row" data-action="reset-confirm"><div><span>Reset demo</span><p>Start again with sample data</p></div>${icon('chevron')}</button></div></div>${extraSettings()}<p class="gentle-note">Moment · One small moment every day.</p>`;}
function submit(){if(state.answer)return;const c=catalog[state.index];const answer=c.type==='Action'?c.sample:state.draft.trim();if(!answer)return;state.answer=answer.slice(0,1200);persist();render();if(modalName==='moment')openMoment();toast('Your part is saved. A little moment, just for you two.');}
function partnerCompletes(){if(!state.answer||state.partnerDone)return;state.partnerDone=true;if(!state.history.some(r=>r.date===state.date)){state.history.unshift({date:state.date,index:state.index,me:state.answer,partner:catalog[state.index].partner});}persist();render();if(modalName==='moment')openMoment();toast('Demo: your partner finished. Your Moment is ready.');}
function nextDay(){if(!state.partnerDone)return;state.date=shiftDay(state.date,1);state.index=nextMomentIndex();state.answer='';state.draft='';state.partnerDone=false;state.revealed=false;state.tab='today';persist();closeModal();render();window.scrollTo(0,0);toast('A new demo day. A new little Moment.');}
function modal(title,body){returnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';$('.modal').focus();}
function closeModal(){if(!$('#modal-root').innerHTML)return;$('#modal-root').innerHTML='';document.body.style.overflow='';modalName=null;if(returnFocus&&document.contains(returnFocus))returnFocus.focus();}
function tools(){modalName='tools';modal('Explore the demo',`<p>Try the whole daily loop: answer, wait for your sample partner, then reveal your shared Moment.</p><label for="moment-select">Today’s Moment type</label><select id="moment-select" ${state.answer?'disabled':''}>${catalog.map((c,i)=>`<option value="${i}" ${i===state.index?'selected':''}>${c.type} — ${c.title}</option>`).join('')}</select><p class="inset-note" style="margin-top:17px">${state.answer?'Finish this Moment before trying the next day, or reset the demo to start again.':'Switch types before answering to explore Questions, Appreciation, Actions, Choices, and Check-ins.'}</p>${state.partnerDone?'<button class="primary" data-action="next">Try the next demo day '+icon('arrow')+'</button>':state.answer?'<button class="primary" data-action="partner-modal">Simulate partner finishing '+icon('arrow')+'</button>':'<button class="primary" data-action="close">Back to our Moment '+icon('arrow')+'</button>'}<button class="secondary" data-weekly="preview">${sundayPreview?"End Sunday preview":"Preview Sunday reflection"}</button><button class="secondary" data-action="welcome">Preview welcome & pairing</button><button class="quiet" data-action="reset-confirm" style="width:100%;margin-top:14px">Reset all demo data</button>`);}
function welcome(){modalName='welcome';modal('A little hello.',`<div class="welcome"><span class="large-logo"><img src="assets/moment-logo.png" alt="Moment logo"></span><h2>A little space.<br>For <em>your kind of us.</em></h2><p>Start fresh, communicate, or stay close from miles apart. Find what helps you two.</p><button class="primary" data-product="focus">Choose what brings us here ${icon('arrow')}</button><button class="secondary" data-action="pair">I have a partner code</button><button class="quiet" data-action="close">Explore with the sample couple</button><p class="eyebrow">A FIRST LOOK AT MOMENT</p><p style="font-size:10px;margin:0">Demo only. No sign-up required.</p></div>`);}
function edit(){modalName='edit';modal('The two of you.',`<p>Try the demo with your names. These stay in this browser and aren’t sent anywhere.</p><form id="names-form"><label for="your-name">Your first name</label><input id="your-name" autocomplete="off" maxlength="24" required value="${esc(state.me)}"><label for="partner-name">Your partner’s first name</label><input id="partner-name" autocomplete="off" maxlength="24" required value="${esc(state.partner)}"><p id="name-error" class="error-text" role="alert"></p><button class="primary" type="submit">Continue demo ${icon('arrow')}</button></form>`);}
function pair(){modalName='pair';modal('Better, together.',`<p>In the real app, one partner will share an invite code and the other will join. Try the sample code below.</p><p class="inset-note">Sample partner code: <strong>MOMENT</strong><br>This is a pairing preview, not a live invitation.</p><form id="pair-form"><label for="pair-code">Partner code</label><input id="pair-code" maxlength="12" placeholder="Enter MOMENT" autocomplete="off" autocapitalize="characters"><p class="error-text" id="pair-error" role="alert"></p><button class="primary" type="submit">Connect sample couple ${icon('arrow')}</button></form>`);}
function privacy(){modalName='privacy';modal('A note on privacy.',`<p>This is a visual, interactive prototype. Here’s what to know while you explore.</p><ul class="privacy-list"><li>Names, answers, and settings are saved only in this browser when browser storage is available.</li><li>Pairing, partner replies, memories, and reminders use sample data. No invitations, messages, or push notifications are sent.</li><li>Hidden answers in this demo are a visual simulation. Real answer privacy will need server-side access rules.</li><li>Wellbeing cards and wearable readings use sample data. Sharing controls only change the partner-view preview; nothing is sent.<\/li><li>No accounts exist here. Account deletion and unpairing will be built with the real account system.</li><li>Use sample answers while testing. Reset demo clears its saved data in this browser.</li></ul><button class="primary" data-action="close">Got it ${icon('check')}</button>`);}
function resetConfirm(){modalName='reset';modal('A fresh little start?',`<p>This will clear names, answers, and settings from this demo in this browser, then restore the sample couple and memories.</p><div class="button-row"><button class="secondary" data-action="close">Keep exploring</button><button class="primary" data-action="reset">Reset demo</button></div>`);}
function memory(date){const r=state.history.find(r=>r.date===date);if(!r)return;modalName='memory';modal(prettyDate(r.date,{month:'long',day:'numeric'}),`<span class="eyebrow" style="color:#a09ab7">${catalog[r.index].type} · OUR MEMORY</span>${reveal(catalog[r.index],r)}<button class="primary" data-action="close">Keep this little memory ${icon('check')}</button>`);}
document.addEventListener('input',e=>{if(e.target.id==='answer'){state.draft=e.target.value.slice(0,1200);persist();$('#count').textContent=state.draft.length+'/1200';$('#submit-answer').disabled=!state.draft.trim();}});
document.addEventListener('change',e=>{if(e.target.id==='moment-select'&&!state.answer){const n=Number(e.target.value);if(Number.isInteger(n)&&n>=0&&n<catalog.length){state.index=n;state.draft='';state.tab='today';persist();render();toast(catalog[n].type+' Moment selected.');}}});
document.addEventListener('submit',e=>{if(e.target.id==='names-form'){e.preventDefault();const me=$('#your-name').value.trim(),partner=$('#partner-name').value.trim();if(!me||!partner){$('#name-error').textContent='Add both first names to continue.';return;}state.me=me.slice(0,24);state.partner=partner.slice(0,24);persist();closeModal();render();toast('Your little corner, made yours.');}if(e.target.id==='pair-form'){e.preventDefault();if($('#pair-code').value.trim().toUpperCase()!=='MOMENT'){$('#pair-error').textContent='That sample code isn’t a match. Try MOMENT.';return;}closeModal();modal('You’re connected.',`<div class="waiting-art">${icon('check')}</div><p style="text-align:center">Your sample couple is connected.<br>Your first Moment is ready.</p><p class="inset-note">Demo preview only. Real pairing will connect two separate accounts.</p><button class="primary" data-action="start">Open our Moment ${icon('arrow')}</button>`);}});
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b){if(e.target.classList.contains('modal-backdrop'))closeModal();return;}
 const a=b.dataset.action;
 if(a==='tab'){closeModal();navigate(b.dataset.tab);}
 else if(a==='choose'){state.draft=b.dataset.value;persist();render();if(modalName==='moment')openMoment();const btn=[...document.querySelectorAll('[data-action="choose"]')].find(el=>el.dataset.value===state.draft);if(btn)btn.focus();}
 else if(a==='submit')submit();
 else if(a==='partner'||a==='partner-modal'){const wasMoment=modalName==='moment';closeModal();partnerCompletes();if(wasMoment)openMoment();}
 else if(a==='reveal'){state.revealed=true;persist();render();if(modalName==='moment')openMoment();}
 else if(a==='next')nextDay();
 else if(a==='close')closeModal();
 else if(a==='welcome')welcome();
 else if(a==='edit')edit();
 else if(a==='pair')pair();
 else if(a==='privacy')privacy();
 else if(a==='memory')memory(b.dataset.date);
 else if(a==='toggle'){if(['reminders','evening'].includes(b.dataset.field)){state[b.dataset.field]=!state[b.dataset.field];persist();render();toast('Reminder preference preview updated. No notifications are sent.');}}
 else if(a==='reset-confirm')resetConfirm();
 else if(a==='reset'){state=initialState();persist();closeModal();render();initializeProduct();toast('Demo reset. A fresh little start.');}
 else if(a==='start'){closeModal();navigate('today');}
});
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const all=[...$('.modal').querySelectorAll('button:not([disabled]),input,select:not([disabled]),textarea,a[href]')];const first=all[0],last=all[all.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===$('.modal'))){e.preventDefault();first?.focus();}}});
$('#demo-tools').addEventListener('click',tools);$('#profile-button').addEventListener('click',()=>navigate('us'));$('#welcome-button').addEventListener('click',welcome);$('.wordmark').addEventListener('click',e=>{e.preventDefault();navigate('today');});
render();
initializeProduct();
